const fs   = require('fs');
const path = require('path');

// ── Read configs ─────────────────────────────────────────────
const cfg  = JSON.parse(fs.readFileSync('/data/scheduler/config.json',      'utf8'));
const ntf  = JSON.parse(fs.readFileSync('/data/notifications/config.json',  'utf8'));

// ── Read job log ─────────────────────────────────────────────
const logFile = '/data/scheduler/job_log.csv';
const rows = fs.existsSync(logFile)
  ? fs.readFileSync(logFile, 'utf8').trim().split('\n').slice(1) // skip header
  : [];

// ── Build table rows ─────────────────────────────────────────
const todayStr = new Date().toISOString().slice(0, 10);
const todayRows = rows
  .filter(r => r.startsWith(todayStr))
  .map(r => {
    const [ts, workflow, status, ...rest] = r.split(',');
    const details = rest.join(',');
    const icon  = status === 'success' ? '✅' : status === 'error' ? '❌' : '⚙️';
    const cls   = status === 'success' ? 'success' : status === 'error' ? 'error' : 'running';
    return `<tr><td>${ts.slice(11)}</td><td>${workflow}</td><td class="${cls}">${icon} ${status}</td><td>${details}</td></tr>`;
  });

const allRows = rows.slice(-100).reverse().map(r => {
  const [ts, workflow, status, ...rest] = r.split(',');
  const details = rest.join(',');
  const cls = status === 'success' ? 'success' : status === 'error' ? 'error' : 'running';
  return `<tr><td>${ts}</td><td>${workflow}</td><td class="${cls}">${status}</td><td>${details}</td></tr>`;
});

const genTime = new Date().toLocaleString('en-IN', { timeZone: cfg.timezone || 'Asia/Kolkata' });

// ── Build workflow quick-links ────────────────────────────────
const host  = cfg.n8n_host || 'localhost';
const port  = cfg.n8n_port || '5679';
const cards = Object.entries(cfg.workflow_form_ids || {}).map(([name, id]) =>
  `<a class="card" href="http://${host}:${port}/form/${id}" target="_blank">▶ ${name}</a>`
).join('\n');

// ── Generate HTML ─────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Automate Hub — Status</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
         background: #0f1117; color: #e2e8f0; padding: 24px; }
  h1 { font-size: 1.6rem; font-weight: 700; color: #fff; }
  h2 { font-size: 1rem; font-weight: 600; color: #94a3b8; margin: 28px 0 10px; text-transform: uppercase; letter-spacing: .06em; }
  .meta { color: #64748b; font-size: .85rem; margin: 4px 0 20px; }
  .cards { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 8px; }
  .card { background: #1e293b; border: 1px solid #334155; border-radius: 8px;
          padding: 10px 16px; color: #7dd3fc; text-decoration: none; font-size: .9rem; }
  .card:hover { background: #2d4263; }
  table { width: 100%; border-collapse: collapse; font-size: .85rem; }
  th { background: #1e293b; color: #94a3b8; padding: 10px 12px; text-align: left; }
  td { padding: 9px 12px; border-bottom: 1px solid #1e293b; }
  tr:hover td { background: #161c2a; }
  .success { color: #4ade80; }
  .error   { color: #f87171; }
  .running { color: #fbbf24; }
  .empty   { color: #475569; padding: 20px 0; }
  @media(max-width:600px) { body { padding: 14px; } table { font-size: .78rem; } }
</style>
</head>
<body>
<h1>⚡ Automate Hub</h1>
<p class="meta">Status page · Generated ${genTime}</p>

<h2>Quick Launch</h2>
<div class="cards">
${cards || '<span class="empty">No workflows configured in scheduler/config.json</span>'}
</div>

<h2>Today's Activity</h2>
<table>
  <tr><th>Time</th><th>Workflow</th><th>Status</th><th>Details</th></tr>
  ${todayRows.length ? todayRows.join('\n  ') : '<tr><td colspan="4" class="empty">No jobs ran today</td></tr>'}
</table>

<h2>Recent History (last 100)</h2>
<table>
  <tr><th>Timestamp</th><th>Workflow</th><th>Status</th><th>Details</th></tr>
  ${allRows.length ? allRows.join('\n  ') : '<tr><td colspan="4" class="empty">No history yet</td></tr>'}
</table>
</body>
</html>`;

// ── Save HTML ─────────────────────────────────────────────────
const outPath = '/data/scheduler/status.html';
fs.writeFileSync(outPath, html, 'utf8');

// ── Telegram summary (optional) ───────────────────────────────
const successCount = todayRows.filter(r => r.includes('class="success"')).length;
const errorCount   = todayRows.filter(r => r.includes('class="error"')).length;
const tgMsg = cfg.send_status_to_telegram && ntf.telegram_bot_token !== 'YOUR_BOT_TOKEN_HERE'
  ? `📋 <b>Status Page Updated</b>\n\n✅ ${successCount} succeeded · ❌ ${errorCount} failed\n📅 ${new Date().toLocaleDateString('en-IN', { timeZone: cfg.timezone })}\n\n<i>Open status.html in your browser</i>`
  : null;

return [{ json: { saved: outPath, today_jobs: todayRows.length, tg_msg: tgMsg,
  tg_token: ntf.telegram_bot_token, tg_chat: ntf.telegram_chat_id } }];
